node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf-8');
// Find ORD-CCC96C context
const idx = str.indexOf('ORD-CCC96C');
if (idx >= 0) {
  // Print surrounding bytes as text
  const start = Math.max(0, idx - 500);
  const end = Math.min(buf.length, idx + 500);
  const slice = buf.slice(start, end);
  // Print printable chars
  let result = '';
  for (const b of slice) {
    if (b >= 32 && b < 127) result += String.fromCharCode(b);
    else result += ' ';
  }
  console.log(result);
}
"

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('latin1');

// Find all table schemas
const schemaPattern = /CREATE TABLE[^;]+/g;
let match;
while ((match = schemaPattern.exec(str)) !== null) {
  console.log(match[0].replace(/[^\x20-\x7E\n]/g, '').trim());
  console.log('---');
}
"

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('latin1');

// Search for order items related to ORD-CCC96C
const idx = str.indexOf('ORD-CCC96C');
// Get more context
for (let i = 0; i < 5; i++) {
  const searchIdx = str.indexOf('ORD-CCC96C', i === 0 ? 0 : str.indexOf('ORD-CCC96C', i * 1000) + 1);
  if (searchIdx < 0) break;
  const start = Math.max(0, searchIdx - 200);
  const end = Math.min(str.length, searchIdx + 300);
  const slice = buf.slice(start, end);
  let result = '';
  for (const b of slice) {
    if (b >= 32 && b < 127) result += String.fromCharCode(b);
    else result += '|';
  }
  console.log('=== Match', i, '===');
  console.log(result);
  console.log();
}
" 2>&1 | head -80

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order details
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get('ORD-CCC96C');
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all('ORD-CCC96C');
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get customer
const user = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.customer_id);
console.log('\n=== CUSTOMER ===');
console.log(JSON.stringify(user, null, 2));

// Get order payments
const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all('ORD-CCC96C');
console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));

// Get order fulfillments
const fulfillments = db.prepare('SELECT * FROM order_fulfillments WHERE order_id = ?').all('ORD-CCC96C');
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

// Get warranties
const warranties = db.prepare('SELECT * FROM warranties WHERE order_id = ?').all('ORD-CCC96C');
console.log('\n=== WARRANTIES ===');
console.log(JSON.stringify(warranties, null, 2));

// Get product details for items
for (const item of items) {
  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(item.product_id);
  console.log('\n=== PRODUCT:', item.product_id, '===');
  console.log(JSON.stringify(product, null, 2));
}
"
